import {expect,test,type Locator,type Page} from '@playwright/test';

test.use({viewport:{width:1024,height:1366},userAgent:'Mozilla/5.0 (iPad; CPU OS 18_0 like Mac OS X) AppleWebKit/605.1.15 Version/18.0 Mobile/15E148 Safari/604.1'});

async function openLesson41(page:Page){await page.goto('/');const chapterTwo=page.locator('.course-chapter-group').nth(1);if(!(await chapterTwo.evaluate(element=>(element as HTMLDetailsElement).open)))await chapterTwo.locator('summary').click();const lesson41=page.getByRole('button',{name:/Открыть урок 41:/});await expect(lesson41).toBeVisible();await expect(lesson41).toBeEnabled();await lesson41.click();await expect(page.locator('.lesson-opening')).toContainText('Составные углы');await page.locator('.lesson-opening-start').click()}
async function nextStage(page:Page,currentId:string,nextId:string){const stage=page.locator(`.lesson-runtime:not([hidden]) .interactive-stage[data-stage-id="${currentId}"]`);await expect(stage).toBeVisible();await stage.locator('.lesson-controls button').last().click();await expect(page.locator(`.lesson-runtime:not([hidden]) .interactive-stage[data-stage-id="${nextId}"]`)).toBeVisible()}
async function setRange(range:Locator,value:string){await range.evaluate((node,next)=>{const setter=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value')?.set;if(!setter)throw new Error('range value setter is unavailable');setter.call(node,String(next));node.dispatchEvent(new Event('input',{bubbles:true}));node.dispatchEvent(new Event('change',{bubbles:true}))},value)}

test('lesson 41 keeps composite-angle reasoning, persistence, construction and mandatory practice stable on iPad',async({page})=>{await page.addInitScript(()=>localStorage.setItem('mathnikita-mentor-auto-guide','false'));await openLesson41(page);await expect(page.locator('[data-stage-id="l41-mission"]')).toBeVisible();await expect(page.locator('.lesson-runtime:not([hidden]) .lesson-controls')).toContainText('Этап 1 из 36');await expect(page.locator('.lesson-runtime:not([hidden]) .angle-diagram svg')).toBeVisible();await nextStage(page,'l41-mission','l41-bridge');await nextStage(page,'l41-bridge','l41-sum-model');await nextStage(page,'l41-sum-model','l41-practice1');const practice1=page.locator('[data-stage-id="l41-practice1"]');await practice1.locator('.inline-answer input').fill('54');await practice1.locator('.check-button').click();await expect(practice1.locator('.instant-feedback.good')).toBeVisible();await practice1.locator('.lesson-controls button').last().click();await expect(page.locator('[data-stage-id="l41-subtraction-model"]')).toBeVisible();const saved=await page.evaluate(()=>JSON.parse(localStorage.getItem('mathnikita-lesson-41-progress-v1')??'null'));expect(saved?.stageIndex).toBe(4);expect(saved?.results?.['l41-p1']).toBe(true);await page.getByRole('button',{name:/Все уроки/}).click();await page.getByRole('button',{name:/Открыть урок 41:/}).click();await page.locator('.lesson-opening-start').click();await expect(page.locator('[data-stage-id="l41-subtraction-model"]')).toBeVisible();await page.evaluate(()=>window.dispatchEvent(new CustomEvent('mathnikita-go-to-stage',{detail:{lessonNumber:41,stageIndex:15}})));const builder=page.locator('[data-stage-id="l41-practice7"]');await expect(builder).toBeVisible();const range=builder.locator('input[type="range"]');await expect(range).toHaveValue('90');await setRange(range,'152');await expect(builder.locator('output')).toHaveText('152°');await builder.locator('.check-button').click();await expect(builder.locator('.instant-feedback.good')).toBeVisible();const collapsedMentor=page.locator('.cat-mentor-collapsed');await expect(collapsedMentor).toBeVisible();await collapsedMentor.click();await expect(page.locator('.cat-mentor-panel')).toBeVisible();await expect(page.locator('.cat-mentor-actions button')).toHaveCount(4);await page.evaluate(()=>window.dispatchEvent(new CustomEvent('mathnikita-go-to-stage',{detail:{lessonNumber:41,stageIndex:35}})));await expect(page.locator('[data-stage-id="l41-summary"]')).toBeVisible();await expect(page.locator('.lesson-reflection')).toHaveCount(1);await expect(page.locator('.extended-practice')).toHaveCount(1);await expect(page.locator('.extended-practice[data-practice-task="l41-extra-01"]')).toBeVisible();const practice=page.locator('.extended-practice');await practice.locator('.extended-practice-input input').fill('54');await practice.locator('.extended-practice-check').click();await expect(practice.locator('.extended-practice-feedback.is-correct')).toBeVisible();await expect(practice.locator('.practice-pythagoras')).toBeVisible();await expect(practice.locator('.practice-pythagoras-actions button')).toHaveCount(4);const overflow=await page.evaluate(()=>document.documentElement.scrollWidth-document.documentElement.clientWidth);expect(overflow).toBeLessThanOrEqual(2)});
